              {/* Render Hotel Recommendation Card */}
              {isHotelType && msg.sender === 'ai' && (
                <HotelRecommendations
                  title="Recommended Hotels For a Three-Night Staycation"
                  onBookNow={(hotel) => {
                    if (!onBookHotel) return;

